CREATE OR REPLACE FUNCTION delivery_private.prevent_store_transfer()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.store_id is distinct from old.store_id then raise exception 'STORE_TRANSFER_FORBIDDEN' using errcode='42501'; end if;
  new.updated_at := now();
  return new;
end;
$function$

